import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs.get("target_snapshot")
    cdc_events = inputs.get("cdc_events")
    watermark = inputs.get("watermark")

    # --- Determine watermark high_ts (events with ts <= high_ts are already applied) ---
    high_ts = None
    if watermark is not None and len(watermark) > 0 and "high_ts" in watermark.columns:
        high_ts = watermark["high_ts"].iloc[0]

    # --- Build initial state from target_snapshot ---
    state = {}
    if target_snapshot is not None:
        for row in target_snapshot.itertuples(index=False):
            item_id = row.item_id
            qty = row.qty_on_hand
            last_ts = row.last_event_ts
            # later rows (if duplicate item_id) overwrite earlier ones
            state[item_id] = [qty, last_ts]

    # --- Filter cdc_events to those not yet applied ---
    if cdc_events is None or len(cdc_events) == 0:
        filtered = cdc_events.iloc[0:0] if cdc_events is not None else pd.DataFrame(
            columns=["event_seq", "event_ts", "op", "item_id", "qty"]
        )
    else:
        if high_ts is not None:
            filtered = cdc_events[cdc_events["event_ts"] > high_ts].copy()
        else:
            filtered = cdc_events.copy()

    # --- Sort strictly by (event_ts, event_seq) to apply sequentially ---
    if len(filtered) > 0:
        filtered = filtered.sort_values(
            by=["event_ts", "event_seq"], kind="mergesort"
        )

    # --- Apply events sequentially ---
    for row in filtered.itertuples(index=False):
        item_id = row.item_id
        op = row.op
        qty = row.qty
        event_ts = row.event_ts

        if op == "R":
            if item_id not in state:
                # absent (never existed or deleted) -> start from 0
                state[item_id] = [0, event_ts]
                state[item_id][0] = state[item_id][0] + qty
                state[item_id][1] = event_ts
            else:
                state[item_id][0] = state[item_id][0] + qty
                state[item_id][1] = event_ts
        elif op == "A":
            # absolute reset; creates item if absent
            state[item_id] = [qty, event_ts]
        elif op == "D":
            # remove item entirely from snapshot
            if item_id in state:
                del state[item_id]
            # if not present, no-op
        else:
            # unknown op - ignore (defensive, legacy artifact only defines R/A/D)
            pass

    # --- Build output DataFrame ---
    if len(state) == 0:
        new_snapshot = pd.DataFrame(columns=["item_id", "qty_on_hand", "last_event_ts"])
    else:
        records = [
            {"item_id": item_id, "qty_on_hand": vals[0], "last_event_ts": vals[1]}
            for item_id, vals in state.items()
        ]
        new_snapshot = pd.DataFrame.from_records(
            records, columns=["item_id", "qty_on_hand", "last_event_ts"]
        )

    return {"new_snapshot": new_snapshot}
